package com.google.gson.internal.bind;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.*;
import java.io.IOException;
import java.io.Reader;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;

public class JsonTreeReader_skipValue_TriageGen1Test {

    private JsonTreeReader reader;

    @Before
    public void setUp() throws IOException {
        reader = Mockito.spy(new JsonTreeReader(new JsonObject()));
    }

    @Test
    public void testSkipValue_WhenPeekIsName() throws IOException {
        Mockito.when(reader.peek()).thenReturn(JsonToken.NAME);
        Mockito.doReturn("testName").when(reader).nextName();

        reader.skipValue();

        Mockito.verify(reader).nextName();
        assertEquals("null", reader.pathNames[reader.stackSize - 2]);
        assertEquals(reader.stackSize - 1, reader.pathIndices[reader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_WhenPeekIsNotName() throws IOException {
        Mockito.when(reader.peek()).thenReturn(JsonToken.BEGIN_OBJECT);

        reader.skipValue();

        Mockito.verify(reader).popStack();
        assertEquals("null", reader.pathNames[reader.stackSize - 1]);
        assertEquals(reader.stackSize - 1, reader.pathIndices[reader.stackSize - 1]);
    }

    @Test(expected = IOException.class)
    public void testSkipValue_WhenPeekThrowsIOException() throws IOException {
        Mockito.when(reader.peek()).thenThrow(new IOException());

        reader.skipValue();
    }

    @Test
    public void testSkipValue_WhenPathNamesAndIndicesAreModified() throws IOException {
        Mockito.when(reader.peek()).thenReturn(JsonToken.END_ARRAY);
        reader.stackSize = 3;
        reader.pathNames = new String[] {"", "", ""};
        reader.pathIndices = new int[] {0, 0, 0};

        reader.skipValue();

        assertEquals("null", reader.pathNames[reader.stackSize - 1]);
        assertEquals(1, reader.pathIndices[reader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_WhenNextNameIsCalled() throws IOException {
        Mockito.when(reader.peek()).thenReturn(JsonToken.NAME);
        Mockito.doReturn("testName").when(reader).nextName();

        reader.skipValue();

        Mockito.verify(reader).nextName();
    }

    @Test
    public void testSkipValue_WhenPopStackIsCalled() throws IOException {
        Mockito.when(reader.peek()).thenReturn(JsonToken.BEGIN_OBJECT);

        reader.skipValue();

        Mockito.verify(reader).popStack();
    }
}
